import { Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../api.service';
import { describeError } from '../errors';
import { ManufacturerDto } from '../models';
import { MessageService } from '../messages/message.service';
import { ManufacturerEditorComponent } from './manufacturer-editor.component';

@Component({
  selector: 'app-manufacturer-page',
  standalone: true,
  imports: [ManufacturerEditorComponent],
  template: `
    <div class="page-title">
      <h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" type="button" class="add-action" (click)="create()">
        New manufacturer
      </button>
    </div>

    <div class="table-wrapper">
      <table id="gwt-debug-manufacturers" class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Edit</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (manufacturer of manufacturers(); track rowKey(manufacturer)) {
            <tr>
              <td>{{ manufacturer.id }}</td>
              <td>{{ manufacturer.name }}</td>
              <td><button type="button" (click)="edit(manufacturer)">Edit</button></td>
              <td><button type="button" (click)="remove(manufacturer)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    @if (editing(); as manufacturer) {
      <app-manufacturer-editor
        [manufacturer]="manufacturer"
        (saved)="onSaved($event)"
        (closed)="editing.set(null)"
      />
    }
  `,
  styles: [
    `
      .table-wrapper {
        margin-top: 20px;
      }
    `,
  ],
})
export class ManufacturerPageComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly manufacturers = signal<ManufacturerDto[]>([]);
  /** Manufacturer being created (no id) or edited; null when the editor is closed. */
  readonly editing = signal<ManufacturerDto | null>(null);

  /**
   * Bumped whenever the editor opens. Rows are keyed by it, so the table is rebuilt
   * behind the popup, as the GWT CellTable was, and the clicked Edit button is replaced.
   */
  private renderGeneration = 0;
  private renderKey = signal(0);

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (list) => this.manufacturers.set(list),
      error: (err) => this.messages.error(`Could not load manufacturers: ${describeError(err)}`),
    });
  }

  rowKey(manufacturer: ManufacturerDto): string {
    return `${this.renderKey()}:${manufacturer.id}`;
  }

  create(): void {
    this.openEditor({ name: '' });
  }

  edit(manufacturer: ManufacturerDto): void {
    this.openEditor({ ...manufacturer });
  }

  onSaved(saved: ManufacturerDto): void {
    const isNew = !this.manufacturers().some((m) => m.id === saved.id);
    if (isNew) {
      this.manufacturers.update((list) => [...list, saved]);
    } else {
      this.manufacturers.update((list) => list.map((m) => (m.id === saved.id ? saved : m)));
    }
    this.editing.set(null);
  }

  remove(manufacturer: ManufacturerDto): void {
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    this.api.deleteManufacturer(manufacturer.id!).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((m) => m.id !== manufacturer.id)),
      error: (err) => this.messages.error(`Could not delete ${manufacturer.name}: ${describeError(err)}`),
    });
  }

  private openEditor(manufacturer: ManufacturerDto): void {
    this.renderKey.set(++this.renderGeneration);
