import { Component, EventEmitter, Input, Output, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService } from '../api.service';
import { describeError } from '../errors';
import { CarDto, RatingDto } from '../models';
import { MessageService } from '../messages/message.service';

/** Create popup for a rating: pick a car, enter a rating, Save (GWT EditRatingView). */
@Component({
  selector: 'app-rating-editor',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="glass"></div>
    <div class="popup" role="dialog" aria-modal="true">
      <div class="field">
        <label for="gwt-debug-ratingCar">Car:</label>
        <select id="gwt-debug-ratingCar" name="car" [(ngModel)]="selectedCar">
          @for (car of cars; track car.id) {
            <option [ngValue]="car">{{ car.manufacturer.name }}/{{ car.model }}</option>
          }
        </select>
      </div>
      <div class="field">
        <label for="gwt-debug-ratingInput">Your rating:</label>
        <input id="gwt-debug-ratingInput" type="number" name="rating" min="0" max="999" [(ngModel)]="rating" />
      </div>
      <div class="actions">
        <button id="gwt-debug-ratingSave" type="button" [disabled]="saving()" (click)="save()">Save</button>
        <button id="gwt-debug-ratingClose" type="button" (click)="closed.emit()">Close</button>
      </div>
    </div>
  `,
  styles: [
    `
      .glass {
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.3);
        z-index: 1000;
      }
      .popup {
        position: fixed;
        top: 30%;
        left: 50%;
        transform: translateX(-50%);
        background: #fff;
        border: 1px solid #45a0ec;
        border-radius: 4px;
        padding: 16px;
        z-index: 1001;
        min-width: 300px;
      }
      .field {
        margin-bottom: 12px;
      }
      .field label {
        display: inline-block;
        width: 100px;
      }
      .actions {
        display: flex;
        gap: 8px;
      }
    `,
  ],
})
export class RatingEditorComponent {
  @Input() cars: CarDto[] = [];
  @Output() saved = new EventEmitter<RatingDto>();
  @Output() closed = new EventEmitter<void>();

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  /** Defaults to the first car, as the GWT picker did. */
  selectedCar: CarDto | null = null;
  rating: number | null = null;
  readonly saving = signal(false);

  constructor() {
    queueMicrotask(() => {
      this.selectedCar ??= this.cars[0] ?? null;
    });
  }

  save(): void {
    if (this.rating === null || this.rating === undefined) {
      this.messages.error('Please enter a rating.');
      return;
    }
    if (!this.selectedCar) {
      this.messages.error('Please pick a car.');
      return;
    }
    const dto: RatingDto = { rating: Number(this.rating), car: { id: this.selectedCar.id } as CarDto };
    this.saving.set(true);
    this.api.saveRating(dto).subscribe({
      next: (savedRating) => {
        this.saving.set(false);
        this.messages.success('Rating saved.');
        this.saved.emit(savedRating);
      },
      error: (err) => {
        this.saving.set(false);
        this.messages.error(`Could not save rating: ${describeError(err)}`);
      },
    });
  }
}

