import { Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../api.service';
import { describeError } from '../errors';
import { ManufacturerRatingDto } from '../models';
import { MessageService } from '../messages/message.service';

@Component({
  selector: 'app-report-page',
  standalone: true,
  template: `
    <div class="page-title">
      <h2>Average Car Rating by Manufacturer</h2>
    </div>

    <div class="table-wrapper">
      <table id="gwt-debug-reports" class="data-table">
        <thead>
          <tr>
            <th>Manufacturer</th>
            <th>Rating</th>
          </tr>
        </thead>
        <tbody>
          @for (row of averages(); track row.manufacturer) {
            <tr>
              <td>{{ row.manufacturer }}</td>
              <td>{{ formatRating(row.rating) }}</td>
            </tr>
          }
        </tbody>
      </table>
    </div>
  `,
  styles: [
    `
      .table-wrapper {
        margin-top: 20px;
      }
    `,
  ],
})
export class ReportPageComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly averages = signal<ManufacturerRatingDto[]>([]);

  ngOnInit(): void {
    this.api.getAverageRatings().subscribe({
      next: (list) => this.averages.set(list),
      error: (err) => this.messages.error(`Could not load the report: ${describeError(err)}`),
    });
  }

  /** Formats like the GWT NumberCell did for a Java double: 3 -> "3.0", 3.5 -> "3.5". */
  formatRating(rating: number): string {
    return Number.isInteger(rating) ? rating.toFixed(1) : String(rating);
  }
}

