import { Component, OnInit, inject, signal } from '@angular/core';

import { ApiService } from '../api.service';
import { describeError } from '../errors';
import { CarDto, RatingDto } from '../models';
import { MessageService } from '../messages/message.service';
import { RatingEditorComponent } from './rating-editor.component';

@Component({
  selector: 'app-rating-page',
  standalone: true,
  imports: [RatingEditorComponent],
  template: `
    <div class="page-title">
      <h2>Ratings</h2>
      <button id="gwt-debug-ratingCreate" type="button" class="add-action" (click)="showEditor.set(true)">
        New rating
      </button>
    </div>

    <div class="table-wrapper">
      <table id="gwt-debug-ratings" class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Car</th>
            <th>Rating</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (rating of ratings(); track rating.id) {
            <tr>
              <td>{{ rating.id }}</td>
              <td>{{ carLabel(rating) }}</td>
              <td>{{ rating.rating }}</td>
              <td><button type="button" (click)="remove(rating)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    @if (showEditor()) {
      <app-rating-editor
        [cars]="cars()"
        (saved)="onSaved($event)"
        (closed)="showEditor.set(false)"
      />
    }
  `,
  styles: [
    `
      .table-wrapper {
        margin-top: 20px;
      }
    `,
  ],
})
export class RatingPageComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly ratings = signal<RatingDto[]>([]);
  readonly cars = signal<CarDto[]>([]);
  readonly showEditor = signal(false);

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (list) => this.ratings.set(list),
      error: (err) => this.messages.error(`Could not load ratings: ${describeError(err)}`),
    });
    // Loaded up front so the car picker is ready as soon as the popup opens.
    this.api.getCars().subscribe({
      next: (list) => this.cars.set(list),
      error: (err) => this.messages.error(`Could not load cars: ${describeError(err)}`),
    });
  }

  /** Same label as the GWT Car column: "Manufacturer/Model". */
  carLabel(rating: RatingDto): string {
    return rating.car ? `${rating.car.manufacturer.name}/${rating.car.model}` : '';
  }

  onSaved(saved: RatingDto): void {
    this.ratings.update((list) => [...list, saved]);
    this.showEditor.set(false);
  }

  remove(rating: RatingDto): void {
    if (!window.confirm(`Are you sure you want to delete${this.carLabel(rating)}?`)) {
      return;
    }
    this.api.deleteRating(rating.id!).subscribe({
      next: () => this.ratings.update((list) => list.filter((r) => r.id !== rating.id)),
      error: (err) => this.messages.error(`Could not delete rating: ${describeError(err)}`),
    });
  }
}

