body {
  font-family: Arial, Helvetica, sans-serif;
  margin: 0;
  color: #222;
}

/* Header and menubar (widget/header) */
.header {
  border-bottom: 1px solid #45a0ec;
}
.header-content {
  width: 1000px;
  margin: 0 auto;
  padding: 10px 0;
  display: flex;
  align-items: center;
}
.application-title {
  font-size: 16px;
  font-weight: bold;
  padding-left: 10px;
}
.menubar {
  margin-left: 30px;
  display: flex;
  gap: 18px;
}
.menubar a {
  color: #45a0ec;
  text-decoration: none;
  font-size: 14px;
  padding: 4px 0;
}
.menubar a:hover {
  text-decoration: underline;
}
.menubar a.active {
  color: #1d6098;
  font-weight: bold;
  border-bottom: 2px solid #1d6098;
}

/* Page layout (1000px column, as in the GWT shell) */
.container {
  width: 1000px;
  margin: 20px auto;
}
.page-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.page-title h2 {
  margin: 0;
  font-size: 22px;
}
.add-action {
  background: #45a0ec;
  color: #fff;
  border: none;
  border-radius: 3px;
  padding: 6px 12px;
  cursor: pointer;
}
.add-action:hover {
  background: #1d6098;
}

/* Tables (CellTable look) */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th,
.data-table td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid #e3e3e3;
}
.data-table th {
  background: #f1f6fc;
  font-weight: bold;
}
.data-table td button {
  cursor: pointer;
}
.data-table th:nth-child(1),
.data-table td:nth-child(1) {
  width: 50px;
}
.data-table th:nth-last-child(-n + 2),
.data-table td:nth-last-child(-n + 2) {
  width: 75px;
}

/* Messages (widget/message): top centre, 300px wide, fade in */
.messages-wrapper {
  position: fixed;
  top: 30px;
  left: 50%;
  width: 300px;
  margin-left: -150px;
  z-index: 200;
}
.message {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  margin-bottom: 6px;
  border-radius: 3px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
  animation: message-fade-in 0.3s ease-in;
}
.message.success {
  background: #dff0d8;
  color: #3c763d;
  border: 1px solid #d6e9c6;
}
.message.error {
  background: #f2dede;
  color: #a94442;
  border: 1px solid #ebccd1;
}
.message-close {
  background: none;
  border: none;
  cursor: pointer;
  font-weight: bold;
  color: inherit;
}
@keyframes message-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

