// Drives headless Chromium through the e2e scenarios (Manufacturers, Ratings, Reports)
// against http://localhost:8888/ng/ using the same element ids/table layout as the Selenium page objects.
const { spawn } = require('child_process');
const http = require('http');
const WebSocket = require('/work/node_modules/ws');

const BASE = 'http://localhost:8888/ng/';
const DEBUG_PORT = 9333;
const failures = [];
let passes = 0;

function check(cond, msg) {
  if (cond) { passes++; console.log('  PASS', msg); }
  else { failures.push(msg); console.log('  FAIL', msg); }
}

function getJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const PRELUDE = `
window.T = {
  sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
  async waitFor(fn, what, timeout = 8000) {
    const start = Date.now();
    for (;;) {
      let v = null;
      try { v = fn(); } catch (e) { v = null; }
      if (v) return v;
      if (Date.now() - start > timeout) throw new Error('timeout waiting for: ' + what);
      await this.sleep(50);
    }
  },
  el(id) { return document.getElementById('gwt-debug-' + id); },
  rows(id) { const t = this.el(id); return t ? t.tBodies[0].rows : null; },
  rowCount(id) { const r = this.rows(id); return r ? r.length : -1; },
  headers(id) { return [...this.el(id).querySelectorAll('thead th')].map((th) => th.textContent.trim()); },
  cell(id, row, col) { return this.rows(id)[row].cells[col].textContent.trim(); },
  lastButton(id, row) { return this.rows(id)[row].cells[this.rows(id)[row].cells.length - 1].querySelector('button'); },
  setInput(input, value) {
    input.value = value;
    input.dispatchEvent(new Event('input', { bubbles: true }));
  },
  successText() { const m = this.el('successMessage'); return m ? m.textContent : null; },
  editor(id) { return this.el(id); },
};
window.__confirmCalls = [];
window.confirm = (msg) => { window.__confirmCalls.push(msg); return true; };
`;

async function main() {
  const chrome = spawn('/usr/bin/chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    `--remote-debugging-port=${DEBUG_PORT}`, `--user-data-dir=/tmp/chrome-check-${Date.now()}`, 'about:blank',
  ], { stdio: 'ignore' });

  let targets;
  for (let i = 0; i < 50; i++) {
    try { targets = await getJson(`http://127.0.0.1:${DEBUG_PORT}/json/list`); break; } catch (e) { await sleep(200); }
  }
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise((r) => ws.on('open', r));

  let nextId = 1;
  const pending = new Map();
  const consoleErrors = [];
  ws.on('message', (raw) => {
    const msg = JSON.parse(raw);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
    if (msg.method === 'Runtime.exceptionThrown') consoleErrors.push(JSON.stringify(msg.params.exceptionDetails).slice(0, 300));
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') consoleErrors.push(JSON.stringify(msg.params.args).slice(0, 300));
  });
  const send = (method, params = {}) => new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  });
  const ev = async (expr) => {
    const res = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (res.result.exceptionDetails) {
      const d = res.result.exceptionDetails;
      throw new Error('page error: ' + (d.exception ? d.exception.description : d.text));
    }
    return res.result.result.value;
  };
  const navigate = async (url) => {
    await send('Page.enable');
    await send('Runtime.enable');
    await send('Page.navigate', { url });
    await sleep(300);
    await ev(PRELUDE);
  };
  const url = () => ev('location.href');
  const clickSel = (sel) => ev(`document.querySelector(${JSON.stringify(sel)}).click(); true`);
  const clickId = (id) => ev(`T.el(${JSON.stringify(id)}).click(); true`);
  const wait = (expr, what, timeout) => ev(`T.waitFor(() => ${expr}, ${JSON.stringify(what)}, ${timeout || 8000})`);
  const setInput = (id, value) => ev(`T.setInput(T.el(${JSON.stringify(id)}), ${JSON.stringify(value)}); true`);

  // ---------- Header / routing ----------
  console.log('Header and routing');
  await navigate(BASE + '#manufacturer');
  await wait(`T.rowCount('manufacturers') > 0`, 'manufacturer rows loaded');
  const menuHrefs = await ev(`[...T.el('menubar').querySelectorAll('a')].map(a => a.getAttribute('href'))`);
  check(menuHrefs.some((h) => h.includes('manufacturer')) && menuHrefs.some((h) => h.includes('rating')) && menuHrefs.some((h) => h.includes('report')),
    `menubar links contain tokens: ${JSON.stringify(menuHrefs)}`);
  check((await url()).includes('#manufacturer'), `URL has #manufacturer: ${await url()}`);
  check(JSON.stringify(await ev(`T.headers('manufacturers')`)) === JSON.stringify(['ID', 'Name', 'Edit', 'Delete']), 'manufacturer headers ID/Name/Edit/Delete');

  // ---------- Manufacturers feature ----------
  console.log('Manufacturers: Clicking on create shows the editor');
  await clickId('create-manufacturer');
  await wait(`T.el('manufacturer-editor') && T.el('manufacturer-editor').offsetParent !== null`, 'editor visible');
  check(true, 'manufacturer editor visible after create');
  await clickId('manufacturer-close');
  await wait(`!T.el('manufacturer-editor')`, 'editor closed');

  console.log('Manufacturers: close leaves table unaltered');
  let before = await ev(`T.rowCount('manufacturers')`);
  await clickId('create-manufacturer');
  await wait(`T.el('manufacturer-editor')`, 'editor');
  await setInput('manufacturer-input', 'Ford');
  await clickId('manufacturer-close');
  await wait(`!T.el('manufacturer-editor')`, 'editor closed');
  check((await ev(`T.rowCount('manufacturers')`)) === before, `row count unchanged (${before})`);

  console.log('Manufacturers: save Plymouth');
  before = await ev(`T.rowCount('manufacturers')`);
  await clickId('create-manufacturer');
  await wait(`T.el('manufacturer-editor')`, 'editor');
  await setInput('manufacturer-input', 'Plymouth');
  await clickId('manufacturer-save');
  await wait(`T.successText() && T.successText().includes('saved')`, 'success message');
  check(/saved/.test(await ev(`T.successText()`)), `success message: "${await ev(`T.successText()`)}"`);
  await wait(`!T.el('manufacturer-editor')`, 'editor closed after save');
  check((await ev(`T.rowCount('manufacturers')`)) === before + 1, 'row count incremented');
  const lastName = await ev(`T.cell('manufacturers', T.rowCount('manufacturers') - 1, 1)`);
  check(lastName === 'Plymouth', `last manufacturer is Plymouth (got ${lastName})`);

  console.log('Manufacturers: edit first row to Ford');
  const editBtn = await ev(`T.rows('manufacturers')[0].cells[2].querySelector('button')`);
  // The button handle is stored in a page global so we can check that it goes stale.
  await ev(`window.__firstEdit = T.rows('manufacturers')[0].cells[2].querySelector('button'); true`);
  await clickSel('#gwt-debug-manufacturers tbody tr:first-child td:nth-last-child(2) button');
  await wait(`T.el('manufacturer-editor')`, 'editor opened from edit');
  await wait(`!window.__firstEdit.isConnected`, 'edit button detached (staleness)');
  check(true, 'edit button went stale when editor opened');
  const prefilled = await ev(`T.el('manufacturer-input').value`);
  check(typeof prefilled === 'string' && prefilled.length > 0, `editor prefilled with "${prefilled}"`);
  await setInput('manufacturer-input', 'Ford');
  await clickId('manufacturer-save');
  await wait(`T.successText() && T.successText().includes('saved')`, 'success after edit');
