  await wait(`T.successText() && T.successText().includes('saved')`, 'rating success message');
  await wait(`T.rowCount('ratings') === ${before + 1}`, 'rating row added');
  check(true, 'a rating is created (success message + row count +1)');

  console.log('Ratings: delete first rating');
  before = await ev(`T.rowCount('ratings')`);
  await ev(`window.__firstRatingDelete = T.rows('ratings')[0].cells[3].querySelector('button'); true`);
  await clickSel('#gwt-debug-ratings tbody tr:first-child td:last-child button');
  await wait(`T.rowCount('ratings') === ${before - 1}`, 'rating removed');
  await wait(`!window.__firstRatingDelete.isConnected`, 'rating delete button detached');
  check(true, 'first rating removed');

