const { spawn } = require('child_process');
const http = require('http');
const WebSocket = require('/work/node_modules/ws');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const getJson = (u) => new Promise((res, rej) => http.get(u, (r) => { let d=''; r.on('data', c => d+=c); r.on('end', () => res(JSON.parse(d))); }).on('error', rej));
(async () => {
  const chrome = spawn('/usr/bin/chromium', ['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9335',`--user-data-dir=/tmp/chrome-lag-${Date.now()}`,'about:blank'], { stdio: 'ignore' });
  let t; for (let i=0;i<50;i++){ try { t = await getJson('http://127.0.0.1:9335/json/list'); break; } catch(e){ await sleep(200);} }
  const page = t.find(x => x.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise(r => ws.on('open', r));
  let id = 1; const pend = new Map();
  ws.on('message', raw => { const m = JSON.parse(raw); if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id);} });
  const send = (method, params={}) => new Promise(r => { const i = id++; pend.set(i, r); ws.send(JSON.stringify({id:i, method, params})); });
  const ev = async (e) => { const r = await send('Runtime.evaluate', {expression: e, awaitPromise: true, returnByValue: true}); return r.result.result ? r.result.result.value : JSON.stringify(r.result); };
  await send('Runtime.enable'); await send('Page.enable');
  await send('Page.navigate', {url: 'http://localhost:8888/ng/#manufacturer'});
  await sleep(1500);
  const count = () => ev(`document.querySelectorAll('#gwt-debug-manufacturers tbody tr').length`);
  for (let run = 0; run < 3; run++) {
    await ev(`document.getElementById('gwt-debug-create-manufacturer').click()`); await sleep(200);
    await ev(`(()=>{const i=document.getElementById('gwt-debug-manufacturer-input'); i.value='Lag${run}'; i.dispatchEvent(new Event('input',{bubbles:true}));})()`); await sleep(50);
    const before = await count();
    await ev(`document.getElementById('gwt-debug-manufacturer-save').click()`);
    const series = [];
    for (let k = 0; k < 15; k++) { series.push(await count()); await sleep(100); }
    console.log(`run ${run}: before=${before} series(100ms steps)=${series.join(',')}`);
  }
  ws.close(); chrome.kill('SIGKILL'); process.exit(0);
})();
EOF
timeout 120 node lag.js

