(async () => {
  const PORT = 9600 + Math.floor(Math.random() * 300);
  const chrome = spawn('/usr/bin/chromium', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${PORT}`,`--user-data-dir=/tmp/chrome-routes-${Date.now()}`,'about:blank'], { stdio: 'ignore', detached: true });
  let t; for (let i=0;i<50;i++){ try { t = await getJson(`http://127.0.0.1:${PORT}/json/list`); break; } catch(e){ await sleep(200);} }
  const page = t.find(x => x.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise(r => ws.on('open', r));
  let id = 1; const pend = new Map();
  ws.on('message', raw => { const m = JSON.parse(raw); if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id);} });
  const send = (method, params={}) => new Promise(r => { const i = id++; pend.set(i, r); ws.send(JSON.stringify({id:i, method, params})); });
  const ev = async (e) => { const r = await send('Runtime.evaluate', {expression: e, awaitPromise: true, returnByValue: true}); return r.result.result ? r.result.result.value : JSON.stringify(r.result); };
  await send('Runtime.enable'); await send('Page.enable');
  for (const [u, expectText, expectUrl] of [
