    await sleep(1500);
    const h2 = await ev(`document.querySelector('h2') && document.querySelector('h2').textContent.trim()`);
    const href = await ev(`location.href`);
    console.log(`${u} -> h2="${h2}" url=${href} ${h2 && h2.includes(expectText) && href.includes(expectUrl) ? 'PASS' : 'FAIL'}`);
  }
  ws.close(); try { process.kill(-chrome.pid, 'SIGKILL'); } catch (e) {}
  process.exit(0);
})();
