package com.gwtplatform.carstore.cucumber.util;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Provides;
import com.google.inject.Singleton;

import cucumber.runtime.java.guice.InjectorSource;

/** Guice bindings for the step definitions: one headless Chromium shared by all scenarios. */
public class CarstoreInjector implements InjectorSource {
    @Override
    public Injector getInjector() {
        return Guice.createInjector(new AbstractModule() {
            @Override
            protected void configure() {
            }

            @Provides
            @Singleton
            WebDriver provideWebDriver() {
                ChromeOptions options = new ChromeOptions();
                String binary = System.getenv("CHROME_BIN");
                if (binary != null && !binary.isEmpty()) {
                    options.setBinary(binary);
                }
                options.addArguments("--headless=new", "--no-sandbox", "--disable-gpu",
                        "--disable-dev-shm-usage", "--window-size=1280,1024");
                final WebDriver driver = new ChromeDriver(options);
                Runtime.getRuntime().addShutdownHook(new Thread() {
                    @Override
                    public void run() {
                        driver.quit();
                    }
                });
                return driver;
            }
        });
    }
}
