package com.gwtplatform.carstore.cucumber.application.widgets;

import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;

import com.gwtplatform.carstore.cucumber.application.BasePage;
import com.gwtplatform.carstore.cucumber.util.ByDebugId;
import com.gwtplatform.carstore.cucumber.util.TestParameters;

import com.google.common.base.Function;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.support.ui.WebDriverWait;

public class MessageWidgetPage extends BasePage {
    private static final String SUCCESS_MESSAGE = "successMessage";

    public boolean hasSuccessMessage() {
        return !successMessages().isEmpty();
    }

    /** Waits until a success message contains the text; the GWT app shows "... saved." after a save. */
    public boolean hasSuccessMessageContaining(final String text) {
        new WebDriverWait(webDriver, TestParameters.TIME_OUT_IN_SECONDS).until(new Function<WebDriver, Boolean>() {
            @Override
            public Boolean apply(WebDriver input) {
                for (WebElement message : successMessages()) {
                    if (message.getText().contains(text)) {
                        return true;
                    }
                }
                return false;
            }
        });
        return true;
    }

    private java.util.List<WebElement> successMessages() {
        return webDriver.findElements(ByDebugId.id(SUCCESS_MESSAGE));
    }
}
