package com.gwtplatform.carstore.cucumber.application.reports;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.ArrayList;

import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;

import com.gwtplatform.carstore.cucumber.application.BasePage;
import com.gwtplatform.carstore.cucumber.util.ByDebugId;

/**
 * The average-rating report. addRating collects the ratings read from the rating table; the check
 * compares every manufacturer's average with the report table row.
 */
public class ReportPage extends BasePage {
    private static final String TABLE_ID = "reports";
    private static final double EPSILON = 1e-9;

    private final Map<String, List<Double>> ratingsByManufacturer = new LinkedHashMap<>();

    /** car is "Manufacturer/Model" as the rating table shows it. */
    public void addRating(String car, String rating) {
        String manufacturer = car.split("/")[0];
        List<Double> ratings = ratingsByManufacturer.get(manufacturer);
        if (ratings == null) {
            ratings = new ArrayList<>();
            ratingsByManufacturer.put(manufacturer, ratings);
        }
        ratings.add(Double.parseDouble(rating));
    }

    public boolean checkManufacturerAverages() {
        WebElement table = waitUntilElementIsLoaded(ByDebugId.id(TABLE_ID));
        List<WebElement> rows = table.findElements(By.xpath("tbody[1]/tr"));
        if (rows.size() != ratingsByManufacturer.size()) {
            return false;
        }
        for (WebElement row : rows) {
            List<WebElement> cells = row.findElements(By.tagName("td"));
            String manufacturer = cells.get(0).getText().trim();
            double shown = Double.parseDouble(cells.get(1).getText().trim());
            List<Double> ratings = ratingsByManufacturer.get(manufacturer);
            if (ratings == null || Math.abs(shown - average(ratings)) > EPSILON) {
                return false;
            }
        }
        return true;
    }

    private static double average(List<Double> values) {
        double sum = 0;
        for (double value : values) {
            sum += value;
        }
        return sum / values.size();
    }
}
